-- Reviewed P99 exchanges using existing quest primitives. Quest faction gating remains intentionally bypassed.
local item_lib = require("items")

function event_say(e)
  if e.message:findi("hail") then
    e.self:Say("It is most unfortunate that you do not have scales to defend your fragile mortal shell, " .. e.other:GetRaceName() .. ", I can only hope that the armor we in the Shrine can provide you with will extend your life another fraction of a century. In addition to that you also might want a [special helm] to cover up that scaleless face of yours. I understand that the Mother could not grace you with all our blessings, but at least we can try to make you look half-way decent.")
  elseif e.message:findi("special helm") then
    e.self:Say("Using my obviously superior skills I can customize a plate helm from the Shrine to suit a " .. e.other:GetRaceName() .. " such as yourself. Give me your Blood Lord's Crown, Scaled Knight's Helm, Helm of Twilight, Akkirus' Crown of the Risen, Cowl of Mortality, Frostreaver's Velium Crown, Crown of the Kromzek Kings, or Crown of the Myrmidon and I shall make you a new helm that will better hide and protect your unscaled features.")
  end
end

